referenceSolutions.javascript:
function tilingRibbonPositiveProofStrip(readings, k) {
  const a=readings; let out=[];
  const m=Math.max(0,...a),dp=Array(m+1).fill(0);dp[0]=1;for(let i=1;i<=m;i++)dp[i]=dp[i-1]+(i>=3?dp[i-3]:0);out=a.map(x=>dp[x]);
  return out.filter(x=>x>0);
}

